#!/usr/bin/env python3
"""Write docs/_search-paths.js: every content page, for Docsify's search plugin.

Docsify's `paths: 'auto'` only indexes links in the sidebar currently on screen,
so a student searching from the home page can't find pages in sections they
haven't opened yet. This gives search the full list instead.

Run from the repo root:  python3 .github/scripts/build-search-paths.py
The deploy workflow regenerates it on every push.
"""
import json
from pathlib import Path

DOCS = Path('docs')
SKIP_DIRS = {'temp'}                       # drafts
SKIP_FILES = {'CLAUDE.md', 'AGENTS.md'}    # AI assistant notes

paths = []
for md in sorted(DOCS.rglob('*.md')):
    rel = md.relative_to(DOCS)
    # Skip _sidebar, _glossary, _coverpage and anything under _tests, _plugins etc.
    if any(part.startswith('_') or part in SKIP_DIRS for part in rel.parts) or md.name in SKIP_FILES:
        continue
    route = '/' + rel.with_suffix('').as_posix()
    if route.endswith('/README'):
        route = route[:-len('README')]     # folder home page, e.g. /history/
    paths.append(route)

out = DOCS / '_search-paths.js'
out.write_text(
    '// Generated by .github/scripts/build-search-paths.py - do not edit by hand.\n'
    'window.$docsify.search.paths = ' + json.dumps(paths, indent=1) + '\n'
)
print(f'{out}: {len(paths)} pages')
